int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
        char *domain;
        char *out;

        if (size > 1024)
                return 0;

        domain = (char *) malloc(size + 1);
        assert(domain != NULL);

        /* 0 terminate */
        memcpy(domain, data, size);
        domain[size] = 0;

        for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++) {
