        if ((size & 3) == 0) {
                uint32_t *u32 = (uint32_t *) malloc(size + 4);
                char *out2 = (char *) malloc(64);

                assert(u32 != NULL);
                assert(out2 != NULL);

                for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++)
                        idn2_to_ascii_4i((uint32_t *) data, size / 4, out2, flags[it]);

                memcpy(u32, data, size);
                u32[size / 4] = 0;

